CREATE TABLE cms.cms_publications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), content_item_id UUID NOT NULL REFERENCES cms.cms_content_items(id), content_revision_id UUID NOT NULL REFERENCES cms.cms_content_revisions(id), locale VARCHAR(10) NOT NULL, published_by_user_id UUID, published_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, publication_status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
